export type ParsedClaimCnftInstruction<
  TProgram extends string = typeof MALLOW_GUMBALL_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    /** Anyone can claim the item for the recorded buyer. */
    payer: TAccountMetas[0];
    /** Gumball machine account. */
    gumballMachine: TAccountMetas[1];
    authorityPda: TAccountMetas[2];
    /** Seller of the cNFT. */
    seller: TAccountMetas[3];
    /** Buyer of the cNFT (recorded at draw). Receives the leaf. */
    buyer: TAccountMetas[4];
    treeConfig: TAccountMetas[5];
    /**
     * `assert_config_line` (which compares the derived asset id to the stored
     * config-line mint).
     */
    merkleTree: TAccountMetas[6];
    logWrapper: TAccountMetas[7];
    compressionProgram: TAccountMetas[8];
    bubblegumProgram: TAccountMetas[9];
    systemProgram: TAccountMetas[10];
    eventAuthority: TAccountMetas[11];
    program: TAccountMetas[12];
  };
  data: ClaimCnftInstructionData;
};

export function parseClaimCnftInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>
): ParsedClaimCnftInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 13) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 13,
      }
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      payer: getNextAccount(),
      gumballMachine: getNextAccount(),
      authorityPda: getNextAccount(),
      seller: getNextAccount(),
      buyer: getNextAccount(),
      treeConfig: getNextAccount(),
      merkleTree: getNextAccount(),
      logWrapper: getNextAccount(),
      compressionProgram: getNextAccount(),
      bubblegumProgram: getNextAccount(),
      systemProgram: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getClaimCnftInstructionDataDecoder().decode(instruction.data),
  };
}
